INSERT INTO public.lesson_sections (lesson_id, type, order_index, speaker, line, translation)
VALUES ((SELECT id FROM public.course_lessons WHERE slug = 'french-b2-retour-a-saint-domingue-writing'), 'dialogue_line', 0, 'Modèle', 'Aujourd’hui, je suis enfin rentré(e) chez moi après un an d’absence. J’ai le sentiment d’être à la fois exactement à ma place et complètement étranger/étrangère. Il me faudra du temps pour réapprendre à habiter cette vie que j’avais quittée.', 'Hoy por fin volví a casa después de un año de ausencia. Tengo la sensación de estar exactamente en mi lugar y a la vez completamente extraño/a. Necesitaré tiempo para volver a habitar esta vida que había dejado.');
