VALUES ((SELECT id FROM public.course_lessons WHERE slug = 'french-b2-candidature-universitaire-speaking'), 'dialogue_line', 0, 'Toi', 'Ce qui a déclenché mon intérêt pour ce domaine, c’est une expérience précise. Par exemple, j’ai... Par ailleurs, je pense pouvoir apporter...', 'Lo que despertó mi interés en este campo fue una experiencia concreta. Por ejemplo, yo... Además, creo que puedo aportar...');
INSERT INTO public.lesson_sections (lesson_id, type, order_index, speaker, line, translation)
VALUES ((SELECT id FROM public.course_lessons WHERE slug = 'french-b2-candidature-universitaire-writing'), 'dialogue_line', 0, 'Modèle', 'Madame, Monsieur, ce qui a déclenché mon intérêt pour cette formation remonte à une expérience précise durant laquelle j’ai découvert ma passion pour ce domaine. Par ailleurs, je suis convaincu(e) que mon parcours m’a préparé(e) à contribuer activement à votre programme.', 'Señora, señor, lo que despertó mi interés por esta formación se remonta a una experiencia concreta durante la cual descubrí mi pasión por este campo. Además, estoy convencido/a de que mi trayectoria me ha preparado para contribuir activamente a su programa.');
