INSERT INTO public.lesson_sections (lesson_id, type, order_index, speaker, line, translation)
VALUES ((SELECT id FROM public.course_lessons WHERE slug = 'french-b2-debats-de-societe-speaking'), 'dialogue_line', 0, 'Toi', 'Il me semble que ce sujet a des avantages réels. Néanmoins, on pourrait objecter que... Dans une certaine mesure, je reconnais cette limite.', 'Me parece que este tema tiene ventajas reales. Sin embargo, se podría objetar que... En cierta medida, reconozco ese límite.');
INSERT INTO public.lesson_sections (lesson_id, type, order_index, speaker, line, translation)
VALUES ((SELECT id FROM public.course_lessons WHERE slug = 'french-b2-debats-de-societe-writing'), 'dialogue_line', 0, 'Modèle', 'Il me semble que les réseaux sociaux offrent de réels avantages pour rester connecté. Néanmoins, ils comportent aussi des risques bien documentés. Dans une certaine mesure, tout dépend de l’usage qu’on en fait. En conclusion, un usage modéré et conscient semble être la meilleure approche.', 'Me parece que las redes sociales ofrecen ventajas reales para mantenerse conectado. Sin embargo, también conllevan riesgos bien documentados. En cierta medida, todo depende del uso que se les dé. En conclusión, un uso moderado y consciente parece ser el mejor enfoque.');
