INSERT INTO public.lesson_sections (lesson_id, type, order_index, speaker, line, translation)
VALUES ((SELECT id FROM public.course_lessons WHERE slug = 'french-b2-le-teletravail-et-lavenir-professionnel-speaking'), 'dialogue_line', 0, 'Toi', 'D’un côté, le télétravail offre de la liberté. De l’autre, il peut créer de l’isolement. Ce dont j’ai besoin, c’est d’un bon équilibre entre les deux.', 'Por un lado, el teletrabajo ofrece libertad. Por otro, puede generar aislamiento. Lo que necesito es un buen equilibrio entre ambos.');
INSERT INTO public.lesson_sections (lesson_id, type, order_index, speaker, line, translation)
VALUES ((SELECT id FROM public.course_lessons WHERE slug = 'french-b2-le-teletravail-et-lavenir-professionnel-writing'), 'dialogue_line', 0, 'Modèle', 'En travaillant à distance, j’ai découvert une grande liberté d’organisation. Cependant, ce dont j’avais besoin, c’était davantage de contact humain. J’ai fini par trouver un équilibre en travaillant parfois dans un espace partagé.', 'Al trabajar a distancia, descubrí una gran libertad de organización. Sin embargo, lo que necesitaba era más contacto humano. Terminé encontrando un equilibrio trabajando a veces en un espacio compartido.');
