VALUES ((SELECT id FROM public.course_lessons WHERE slug = 'french-b2-cinema-et-critique-speaking'), 'dialogue_line', 0, 'Toi', 'Ce qui m’a marqué(e) dans ce film, c’est... Ce que j’ai moins aimé, c’est... En conclusion, je recommande ce film pour...', 'Lo que me marcó de esta película fue... Lo que me gustó menos fue... En conclusión, recomiendo esta película para...');
INSERT INTO public.lesson_sections (lesson_id, type, order_index, speaker, line, translation)
VALUES ((SELECT id FROM public.course_lessons WHERE slug = 'french-b2-cinema-et-critique-writing'), 'dialogue_line', 0, 'Modèle', 'Ce qui m’a le plus marqué dans ce film, c’est la subtilité de la mise en scène. Ce que j’ai particulièrement apprécié, c’est le jeu des actrices principales. Cependant, le rythme est parfois lent. Je recommande ce film aux amateurs de drames familiaux.', 'Lo que más me marcó de esta película fue la sutileza de la puesta en escena. Lo que aprecié especialmente fue la actuación de las actrices principales. Sin embargo, el ritmo es a veces lento. Recomiendo esta película a los amantes de los dramas familiares.');
