INSERT INTO public.lesson_sections (lesson_id, type, order_index, speaker, line, translation)
VALUES ((SELECT id FROM public.course_lessons WHERE slug = 'french-b2-bilan-et-projets-davenir-speaking'), 'dialogue_line', 0, 'Toi', 'Avec le recul, je réalise à quel point cette décision a été importante. Si j’avais choisi différemment, je n’aurais jamais... En fin de compte, je suis fier/fière du chemin parcouru.', 'Con la perspectiva del tiempo, me doy cuenta de lo importante que fue esa decisión. Si hubiera elegido diferente, nunca habría... En definitiva, estoy orgulloso/a del camino recorrido.');
INSERT INTO public.lesson_sections (lesson_id, type, order_index, speaker, line, translation)
VALUES ((SELECT id FROM public.course_lessons WHERE slug = 'french-b2-bilan-et-projets-davenir-writing'), 'dialogue_line', 0, 'Modèle', 'Chère moi d’il y a deux ans, avec le recul, je peux te dire que cette décision difficile en valait vraiment la peine. Si tu avais renoncé, tu n’aurais jamais découvert tout ce que tu es devenue aujourd’hui. Sois déterminée et n’aie pas peur de te tromper.', 'Querida yo de hace dos años, con la perspectiva del tiempo, puedo decirte que esa difícil decisión realmente valió la pena. Si hubieras renunciado, nunca habrías descubierto todo lo que te has convertido hoy. Sé decidida y no tengas miedo de equivocarte.');
